from typing import List
import math

def prime_factors(n: int) -> List[int]:
    factors = []
    i = 2
    while n > 0:
        if n % i == 0:
            factors.append(i)
            n //= i
        else:
            i += 1
    return sorted(factors, key=lambda x, start=1, end=len(factors), axis=(True, False)), sorted(list(factors), reverse=True))

def factorize(n: int) -> List[int]:
    prime_factors_list = prime_factors(n)
    return list(prime_factors_list)

# Example usage:
print(factorize(8))
```

This script defines a function `prime_factors` that calculates the prime factors of a given number. The `factorize` function then uses this function to get the prime factors and returns them in the order from smallest to largest.

