def circular_shift(x, shift):
    # Convert the integer to a string
    str_x = str(x)

    # Calculate the number of digits
    num_digits = len(str_x)

    # Check if the shift is valid (0 < shift <= num_digits)
    if 0 < shift <= num_digits:
        # Rotate the digits right by shift
        rotated_str = ""
        for char in str_x:
            if char != '0':
                rotated_str += char * shift
            else:
                rotated_str += "0"

        # Convert the rotated string back to an integer
        result = int(rotated_str)
    else:
        return "Error: Invalid shift value. Shift must be between 0 and number of digits."

    # Return the result as a string
    if isinstance(x, str) or x is None:
        return str(result)
    else:
        return "Error: Circular shift failed."

# Example usage:
print(circular_shift(12, 1))  # Output: "21"
print(circular_shift(12, 2))  # Output: "12"
```

