from collections import deque

def digits(n):
    """Given a positive integer n, return the product of the odd digits.
    Return 0 if all digits are even."""
    # Convert the number to string for easy iteration
    num_str = str(n)

    # Initialize variables to store odd and even digits
    odd_digits = deque()
    even_digits = deque()

    # Iterate over each character in the string representation of n
    for char in num_str:
        if int(char) % 2 != 0: 
            # If it's an odd digit, add it to the list
            odd_digits.append(int(char))
        else:
            # If it's an even digit, add it to the list
            even_digits.append(int(char))

    # Calculate the product of all digits (if any)
    if len(odd_digits) == 0 and len(even_digits) == 0: 
        return 0
    elif len(odd_digits) > 0 and len(even_digits) == 0:
        return math.prod(odd_digits)
    else:
        # Return the product of all odd digits if any
        return math.prod(odd_digits)
